// One item holding every scenario, so the other nodes read the same data.
return [{ json: { CONTRACTS, EVENTS, SIM_DATES, CHECKPOINTS } }];

const stateOn = (planStages, events, today) => {
  const stages = planStages.map((s) => ({ ...s }));
  (events || []).filter((e) => e[0] <= today).forEach(([date, key, status, note]) => {
    const s = stages.find((x) => x.stage_key === key);
    s.status = status; s.status_since = date; s.done_on = status === 'done' ? date : '';
    if (note) s.note = note;
  });
  return stages;
};

const { EVENTS, SIM_DATES, CHECKPOINTS } = $('Test scenarios').first().json;
// For every simulated date, apply only the stage updates that had happened by then.
const plans = $input.all().map((i) => i.json);
const runFor = (today, extra) => ({ json: {
  eval_run: true,
  today,
  eval_projects: plans.map(({ stages, ...p }) => p),
  eval_stages: plans.flatMap((p) => stateOn(p.stages, EVENTS[p.project_id], today)),
  ...extra,
} });
// Reminder repeat cases bring their own history of earlier reminders.
return SIM_DATES.map((today) => runFor(today, {}))
  .concat(CHECKPOINTS.filter((cp) => cp.type === 'repeat').map((cp) => runFor(cp.date, { eval_tag: cp.id, eval_reminder_history: cp.history })));

const stateOn = (planStages, events, today) => {
  const stages = planStages.map((s) => ({ ...s }));
  (events || []).filter((e) => e[0] <= today).forEach(([date, key, status, note]) => {
    const s = stages.find((x) => x.stage_key === key);
    s.status = status; s.status_since = date; s.done_on = status === 'done' ? date : '';
    if (note) s.note = note;
  });
  return stages;
};

const { EVENTS, CHECKPOINTS } = $('Test scenarios').first().json;
// Each case is a form submission on a given day, against the plan as it stood the day before.
const plans = $('Build plans with OT Contract Signed').all().map((i) => i.json);
return CHECKPOINTS.filter((cp) => cp.type === 'update').map((cp) => {
  const plan = plans.find((p) => p.project_id === cp.p);
  const { stages, ...project } = plan;
  return { json: {
    eval_run: true, eval_case: cp.id, project_id: cp.p, today: cp.date, date: cp.input.date || '',
    stage_key: cp.input.stage_key, status: cp.input.status, note: cp.input.note || '',
    eval_project: project,
    eval_stages: stateOn(stages, EVENTS[cp.p].filter((e) => e[0] < cp.date), cp.date),
  } };
});

const CHECKPOINTS = $('Test scenarios').first().json.CHECKPOINTS;
// ===== COMPARE: expected vs actual for every checkpoint. =====
function compareAll(plans, daily, portfolios, updates) {
  const rows = [];
  const flagSet = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean).sort();
  let falseFlags = 0;
  let missedFlags = 0;

  CHECKPOINTS.forEach((cp) => {
    let expected = '';
    let actual = '';
    let detail = '';
    if (cp.type === 'plan') {
      const plan = plans[cp.p];
      expected = cp.expected;
      if (!plan) actual = 'no plan returned';
      else if (cp.field === 'stage_keys') actual = plan.stages.map((s) => s.stage_key).join(',');
      else if (cp.field === 'warning') actual = plan.warnings.length ? 'yes' : 'no';
      else {
        const [what, key] = cp.field.split(':');
        const s = plan.stages.find((x) => x.stage_key === key);
        actual = String(what === 'due' ? s.due_date : what === 'days' ? s.business_days : what === 'owner' ? s.owner : s.stage_name);
      }
      detail = plan ? plan.warnings.join('; ') : '';
    } else if (cp.type === 'daily') {
      const r = daily.find((x) => x.project_id === cp.p && x.check_date === cp.date && !x.eval_tag);
      if (!r) { expected = cp.health || cp.expected; actual = 'no result'; }
      else if (cp.field) {
        expected = cp.expected;
        actual = String(r[cp.field]);
      } else {
        const expFlags = flagSet(cp.flags);
        const actFlags = flagSet(r.flags.join(','));
        const extra = actFlags.filter((f) => !expFlags.includes(f));
        const missing = expFlags.filter((f) => !actFlags.includes(f));
        falseFlags += extra.length;
        missedFlags += missing.length;
        expected = cp.health + ' | ' + (expFlags.join(', ') || 'no flags');
        actual = r.health + ' | ' + (actFlags.join(', ') || 'no flags');
        if (cp.reminder_to) {
          const sent = r.reminders.some((m) => m.owner === cp.reminder_to);
          expected += ' | reminder to ' + cp.reminder_to;
          actual += sent ? ' | reminder to ' + cp.reminder_to : ' | no reminder to ' + cp.reminder_to;
        }
        detail = r.reminders.map((m) => m.to + ': ' + m.text).join(' / ');
      }
    } else if (cp.type === 'repeat') {
      const r = daily.find((x) => x.project_id === cp.p && x.eval_tag === cp.id);
      expected = cp.expected;
      if (!r) actual = 'no result';
      else {
        actual = (r.reminders.length ? 'sent' : r.reminders_held.length ? 'held' : 'none') + ' | ' + r.health;
        detail = r.reminders_held.map((m) => m.stage + ' last sent ' + m.last_sent).join(' / ') || r.reminders.map((m) => m.text).join(' / ');
      }
    } else if (cp.type === 'portfolio') {
      const pf = portfolios[cp.date];
      expected = cp.expected;
      actual = pf ? String(pf[cp.field]) : 'no result';
    } else if (cp.type === 'update') {
      const u = updates[cp.id];
      expected = cp.expected;
      if (!u) actual = 'no result';
      else if (!u.ok) { actual = 'rejected'; detail = u.error; }
      else if (cp.expected === 'handover') {
        const note = u.handover_note || '';
        const good = /HANDOVER/.test(note) && /Open items: Handover to CSM/.test(note) && /Contacts: technical contact/.test(note) && /Next step:/.test(note);
        actual = good ? 'handover' : (note ? 'handover note incomplete' : 'accepted, no handover note');
        detail = note.split('\n').slice(1, 3).join(' ');
      } else {
        actual = u.stage && u.stage.status_since === cp.date ? 'accepted' : 'accepted, wrong date';
      }
    }
    rows.push({ checkpoint: cp.id, type: cp.type, project: cp.p || 'all', sim_date: cp.date || '', what_it_tests: cp.what, expected, actual, passed: expected === actual, detail });
  });

  const passed = rows.filter((r) => r.passed).length;
  return {
    rows,
    summary: { checkpoints: rows.length, passed, failed: rows.length - passed, pass_pct: Math.round((passed / rows.length) * 100), false_flags: falseFlags, missed_flags: missedFlags,
      mistakes: rows.filter((r) => !r.passed).map((r) => r.checkpoint + ': expected ' + r.expected + ', got ' + r.actual).join(' || ') },
  };
}

const plans = {};
$('Build plans with OT Contract Signed').all().forEach((i) => {
  plans[i.json.project_id] = { stages: i.json.stages, warnings: String(i.json.plan_warnings || '').split('; ').filter(Boolean) };
});
const dailyRows = $('Run OT Daily Check for each date').all().map((i) => i.json);
const daily = dailyRows.filter((r) => r.row_type === 'project');
const portfolios = {};
dailyRows.filter((r) => r.row_type === 'portfolio' && !r.eval_tag).forEach((r) => { portfolios[r.check_date] = r.portfolio; });
const updates = {};
$input.all().forEach((i) => { updates[i.json.eval_case] = i.json; });

const out = compareAll(plans, daily, portfolios, updates);
const runAt = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm');
const runId = 'rules-' + $now.toFormat('yyyyMMddHHmmss');
return out.rows.map((r) => ({ json: { run_id: runId, run_at: runAt, suite: 'rules', ...r, summary: out.summary } }));
